{"files":[{"content":"/* Cloud Cargo core: deterministic and deliberately free of browser/DOM APIs. */
(function () {
  'use strict';
  function rng(seed) { var x = (seed >>> 0) || 1; return function () { x ^= x << 13; x ^= x >>> 17; x ^= x << 5; return (x >>> 0) / 4294967296; }; }
  function shuffle(a, r) { for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  function makeBoard(seed, stage) {
    var r = rng(((seed >>> 0) + Math.imul(stage + 17, 747796405)) >>> 0);
    var count = 4 + stage, bays = stage === 0 ? 2 : 3, groups = [], cards = [], i, b;
    for (b = 0; b < bays; b++) groups.push([]);
    /* Seed each bay first, then distribute the remaining finite cargo. */
    for (i = 0; i < count; i++) groups[i % bays].push(i);
    var raw = [];
    for (i = 0; i < count; i++) raw.push({ mass: 1 + Math.floor(r() * 5), energy: stage === 0 ? 0 : Math.floor(r() * 4), group: i % bays });
    /* The final manifest always has a same-mass, different-energy exchange.
       It proves an apparently valid mass partition can still be rejected. */
    if (stage === 2) {
      var m = 1 + Math.floor(r() * 5), e = Math.floor(r() * 3);
      raw[0] = { mass: m, energy: e, group: 0 };
      raw[1] = { mass: m, energy: e + 1, group: 1 };
      groups = [[], [], []];
      for (i = 0; i < count; i++) groups[raw[i].group].push(i);
    }
    var target = [];
    for (b = 0; b < bays; b++) {
      var mass = 0, energy = 0;
      for (i = 0; i < raw.length; i++) if (raw[i].group === b) { mass += raw[i].mass; energy += raw[i].energy; }
      target.push({ mass: mass, energy: stage === 0 ? null : energy });
    }
    /* Bay order and card order are separately shuffled; no solution fields escape. */
    var order = shuffle(Array.from({ length: bays }, function (_, n) { return n; }), r);
    var mapped = {};
    for (b = 0; b < bays; b++) mapped[order[b]] = b;
    for (i = 0; i < raw.length; i++) cards.push({ mass: raw[i].mass, energy: raw[i].energy, bay: -1 });
    shuffle(cards, r);
    return { cards: cards, bays: order.map(function (old) { return { mass: target[old].mass, energy: target[old].energy }; }) };
  }
  function installBoard(s, stage) { var board = makeBoard(s.seed, stage); s.cards = board.cards; s.bays = board.bays; s.selectedCard = 0; s.focus = 0; s.validation = 0; s.message = 'SELECT A CRATE, THEN A BAY'; }
  function totals(s, index) { var m = 0, e = 0; for (var i = 0; i < s.cards.length; i++) if (s.cards[i].bay === index) { m += s.cards[i].mass; e += s.cards[i].energy; } return { mass: m, energy: e }; }
  function exact(s) { for (var i = 0; i < s.bays.length; i++) { var t = totals(s, i), b = s.bays[i]; if (t.mass !== b.mass || (b.energy !== null && t.energy !== b.energy)) return false; } for (var j = 0; j < s.cards.length; j++) if (s.cards[j].bay < 0) return false; return true; }
  function choosePointer(s, p) {
    if (!p) return false;
    var x = p.x, y = p.y, i;
    if (y >= 0.43 && y <= 0.92) { var row = y < 0.70 ? 0 : 1, col = Math.min(2, Math.max(0, Math.floor(x * 3))); i = row * 3 + col; if (i < s.cards.length) { s.selectedCard = i; s.focus = i; s.interactions++; s.message = 'CRATE ' + (i + 1) + ' READY — CHOOSE BAY'; return true; } }
    if (y >= 0.08 && y <= 0.39) { i = Math.min(s.bays.length - 1, Math.max(0, Math.floor(x * s.bays.length))); assign(s, i); return true; }
    return false;
  }
  function assign(s, bay) { var c = s.cards[s.selectedCard]; if (!c) return; if (c.bay !== bay) { c.bay = bay; s.assignments++; s.interactions++; s.validation = 0; s.message = 'CRATE ' + (s.selectedCard + 1) + ' LOADED TO BAY ' + String.fromCharCode(65 + bay); } }
  function activate(s) { if (s.focus < s.cards.length) { s.selectedCard = s.focus; s.interactions++; s.message = 'CRATE ' + (s.focus + 1) + ' READY — CHOOSE BAY'; } else assign(s, s.focus - s.cards.length); }
  var core = {
    create: function (seed) { var s = { seed: seed >>> 0, tick: 0, stage: 0, score: 0, assignments: 0, interactions: 0, focus: 0, selectedCard: 0, validation: 0, dispatchHold: 0, message: 'SELECT A CRATE, THEN A BAY', cards: [], bays: [], terminalReason: '' }; installBoard(s, 0); return s; },
    step: function (s, input) {
      s.tick++; input = input || {};
      if (s.terminalReason) return s;
      if (s.stage === 3) { if (s.tick >= 900) s.terminalReason = 'complete'; return s; }
      if (s.tick >= 3000) { s.terminalReason = 'incomplete'; s.message = 'TIME EXPIRED — REVIEW THE MANIFEST'; return s; }
      if (s.dispatchHold > 0) { s.dispatchHold--; if (s.dispatchHold === 0) { if (s.stage >= 3) s.message = 'FLEET DEPARTING'; else installBoard(s, s.stage); } return s; }
      if (input.pointer) choosePointer(s, input.pointer);
      else {
        var total = s.cards.length + s.bays.length;
        if (input.x) { s.focus = (s.focus + (input.x > 0 ? 1 : -1) + total) % total; s.interactions++; }
        if (input.action) activate(s);
      }
      if (exact(s)) { s.validation++; s.message = 'MANIFEST VERIFIED — HOLDING FOR DISPATCH'; if (s.validation >= 30) { s.stage++; s.score += 250 + Math.max(0, 120 - Math.floor(s.tick / 30)); s.dispatchHold = 54; s.validation = 0; s.message = s.stage === 3 ? 'ALL THREE AIRSHIPS DISPATCHED!' : 'AIRSHIP LIFTING OFF!'; } } else if (s.validation) s.validation = 0;
      return s;
    },
    observe: function (s) { return { tick: s.tick, score: s.score, progress: Math.min(100, Math.floor(s.tick * 100 / 3000)), interactions: s.interactions, entities: s.cards.length + s.bays.length + 3 }; },
    terminal: function (s) { return !!s.terminalReason; }
  };
  window.CloudCargoCore = core;
}());
