  'use strict';
  var shell = document.querySelector('[data-cargo-shell]');
  var score = document.querySelector('[data-game-score]');
  var best = document.querySelector('[data-cargo-best]');
  var goal = document.querySelector('[data-cargo-goal-progress]');
  var result = document.querySelector('[data-cargo-result]');
  var detail = document.querySelector('[data-cargo-result-detail]');
  var reduced = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : { matches: false };
  function setReduced() { shell.setAttribute('data-reduced-motion', reduced.matches ? 'true' : 'false'); }
  setReduced();
  if (reduced.addEventListener) reduced.addEventListener('change', setReduced); else if (reduced.addListener) reduced.addListener(setReduced);
  fetch('./manifest.json').then(function (r) { return r.json(); }).then(function (metadata) {
    var kit = PlayJoltGameKit.create({
      core: CloudCargoCore,
      canvas: document.querySelector('[data-game-canvas]'),
      metadata: metadata,
      draw: function (ctx, snapshot, options) {
        var copy = snapshot || {}, state = copy.state || {};
        options = options || {}; options.reducedMotion = reduced.matches;
        score.textContent = String(Number(copy.score != null ? copy.score : state.score || 0));
        best.textContent = String(Number(copy.best || 0));
        goal.textContent = String(state.stage || 0) + '/3';
        if (state.terminalReason) {
          result.hidden = false;
          result.textContent = state.terminalReason === 'complete' ? 'SKYPORT COMPLETE' : 'CARGO INCOMPLETE';
          detail.textContent = state.terminalReason === 'complete' ? '3/3 dispatched • ' + (state.assignments || 0) + ' cargo assignments • fleet departure confirmed' : (state.stage || 0) + '/3 dispatched • ' + (state.assignments || 0) + ' assignments • Retry: match every bay total.';
        } else { result.hidden = true; detail.textContent = ''; }
        CargoPresentation.draw(ctx, copy, options);
      }
    });
    window.CloudCargoKit = kit;
  }).catch(function (e) { var el = document.querySelector('[data-game-error]'); el.hidden = false; el.textContent = 'Unable to prepare local practice: ' + e.message; });
}());
