  'use strict';
  var lastReduced = false;
  function rr(ctx, x, y, w, h, r, fill, stroke) { ctx.beginPath(); ctx.roundRect(x, y, w, h, r); if (fill) { ctx.fillStyle = fill; ctx.fill(); } if (stroke) { ctx.strokeStyle = stroke; ctx.stroke(); } }
  function text(ctx, t, x, y, size, color, align) { ctx.fillStyle = color; ctx.font = '700 ' + size + 'px system-ui,sans-serif'; ctx.textAlign = align || 'center'; ctx.textBaseline = 'middle'; ctx.fillText(t, x, y); }
  function totals(s, bay) { var m = 0, e = 0; (s.cards || []).forEach(function (c) { if (c.bay === bay) { m += c.mass; e += c.energy; } }); return { mass: m, energy: e }; }
  function draw(ctx, snap, opt) {
    var s = snap.state || {}, w = opt.width || ctx.canvas.width, h = opt.height || ctx.canvas.height, W = w, H = h;
    lastReduced = !!opt.reducedMotion;
    ctx.clearRect(0, 0, W, H);
    var bg = ctx.createLinearGradient(0, 0, 0, H); bg.addColorStop(0, '#101b39'); bg.addColorStop(1, '#21375a'); ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);
    /* fixed, quiet stars */ ctx.fillStyle = '#8adbe0'; for (var q = 0; q < 19; q++) { var sx = ((q * 73 + 31) % 100) / 100 * W, sy = ((q * 47 + 9) % 38) / 100 * H; ctx.fillRect(sx, sy, 2, 2); }
    var bays = s.bays || [], cards = s.cards || [];
    text(ctx, 'MANIFEST ' + Math.min(3, (s.stage || 0) + 1), W / 2, H * .045, Math.max(12, W * .038), '#f9e9bd');
    for (var i = 0; i < bays.length; i++) {
      var bw = W / bays.length * .82, bx = (i + .5) / bays.length * W - bw / 2, by = H * .10, bh = H * .27;
      var t = totals(s, i), b = bays[i], selectedBay = (s.focus === cards.length + i), match = t.mass === b.mass && (b.energy === null || t.energy === b.energy);
      rr(ctx, bx, by, bw, bh, 13, '#f6e7bd', selectedBay ? '#ff7a5c' : (match ? '#81e5c5' : '#6bcbd3'));
      ctx.lineWidth = selectedBay ? 4 : 2;
      text(ctx, 'BAY ' + String.fromCharCode(65 + i), bx + bw / 2, by + bh * .18, Math.max(12, W * .034), '#17233d');
      /* cyan envelope silhouette */ ctx.fillStyle = '#48c7d2'; ctx.beginPath(); ctx.ellipse(bx + bw / 2, by + bh * .37, bw * .28, bh * .11, 0, 0, Math.PI * 2); ctx.fill(); ctx.fillStyle = '#274265'; ctx.fillRect(bx + bw * .43, by + bh * .46, bw * .14, bh * .09);
      text(ctx, 'M ' + t.mass + ' / ' + b.mass, bx + bw / 2, by + bh * .66, Math.max(12, W * .032), '#17233d');
      text(ctx, b.energy === null ? 'MASS ONLY' : 'E ' + t.energy + ' / ' + b.energy, bx + bw / 2, by + bh * .82, Math.max(12, W * .030), match ? '#16856e' : '#344764');
    }
    for (var c = 0; c < cards.length; c++) {
      var col = c % 3, row = Math.floor(c / 3), cw = W * .275, ch = H * .18, cx = (col + .5) / 3 * W - cw / 2, cy = H * (.47 + row * .25);
      var card = cards[c], chosen = s.selectedCard === c, focussed = s.focus === c;
      rr(ctx, cx, cy, cw, ch, 12, chosen ? '#ff8065' : '#f6e7bd', focussed ? '#fff3d4' : '#36506f'); ctx.lineWidth = focussed ? 4 : 2;
      text(ctx, 'CRATE ' + (c + 1), cx + cw / 2, cy + ch * .21, Math.max(12, W * .029), '#17233d');
      text(ctx, 'MASS ' + card.mass, cx + cw / 2, cy + ch * .49, Math.max(12, W * .032), '#17233d');
      text(ctx, (s.stage === 0 ? 'STANDARD' : 'ENERGY ' + card.energy) + (card.bay >= 0 ? '  •  ' + String.fromCharCode(65 + card.bay) : ''), cx + cw / 2, cy + ch * .75, Math.max(12, W * .026), '#344764');
    }
    if (s.message) { rr(ctx, W * .08, H * .94, W * .84, H * .045, 8, '#13233e'); text(ctx, s.message, W / 2, H * .962, Math.max(12, W * .027), '#bdf4df'); }
    /* three fleet markers make expedition progress visible even during a board. */
    for (var k = 0; k < 3; k++) { ctx.fillStyle = k < (s.stage || 0) ? '#82e8c7' : '#50627d'; ctx.beginPath(); ctx.ellipse(W * (.42 + k * .08), H * .075, W * .025, H * .012, 0, 0, Math.PI * 2); ctx.fill(); }
  }
  window.CargoPresentation = { draw: draw, snapshot: function () { return { reducedMotion: lastReduced, particles: 0, activeVoices: 0 }; } };
}());
